public class StandardDuplicateProbe {
 public static Map<String,Object> graph(Datacloud.DuplicateResult d) {
  List<Object> matches=new List<Object>();
  for(Datacloud.MatchResult m:d.getMatchResults()) {
   List<Object> records=new List<Object>();
   for(Datacloud.MatchRecord r:m.getMatchRecords()) {List<String> fields=new List<String>();fields.addAll(r.getRecord().getPopulatedFieldsAsMap().keySet());fields.sort();records.add(new Map<String,Object>{'type'=>String.valueOf(r.getRecord().getSObjectType()),'confidence'=>r.getMatchConfidence(),'fields'=>fields});}
   matches.add(new Map<String,Object>{'entity'=>m.getEntityType(),'rule'=>m.getRule(),'engine'=>m.getMatchEngine(),'size'=>m.getSize(),'success'=>m.isSuccess(),'errors'=>m.getErrors().size(),'records'=>records});
  }
  return new Map<String,Object>{'rule'=>d.getDuplicateRule(),'entity'=>d.getDuplicateRuleEntityType(),'allowSave'=>d.isAllowSave(),'message'=>d.getErrorMessage(),'matches'=>matches};
 }
 public static List<Object> found(List<SObject> rows) {
  List<Object> out=new List<Object>();for(Datacloud.FindDuplicatesResult f:Datacloud.FindDuplicates.findDuplicates(rows)) {List<Object> duplicates=new List<Object>();for(Datacloud.DuplicateResult d:f.getDuplicateResults()) duplicates.add(graph(d));out.add(new Map<String,Object>{'success'=>f.isSuccess(),'errors'=>f.getErrors().size(),'duplicates'=>duplicates});}return out;
 }
 public static List<Object> byIds(List<Id> ids) {
  List<Object> out=new List<Object>();for(Datacloud.FindDuplicatesResult f:Datacloud.FindDuplicatesByIds.findDuplicatesByIds(ids)) {List<Object> duplicates=new List<Object>();for(Datacloud.DuplicateResult d:f.getDuplicateResults()) duplicates.add(graph(d));out.add(new Map<String,Object>{'success'=>f.isSuccess(),'errors'=>f.getErrors().size(),'duplicates'=>duplicates});}return out;
 }
 public static Map<String,Object> save(Database.SaveResult r) {
  List<Object> errors=new List<Object>();for(Database.Error e:r.getErrors()) {Map<String,Object> x=new Map<String,Object>{'status'=>String.valueOf(e.getStatusCode()),'message'=>e.getMessage(),'fields'=>e.getFields(),'duplicateError'=>e instanceof Database.DuplicateError};if(e instanceof Database.DuplicateError)x.put('duplicate',graph(((Database.DuplicateError)e).getDuplicateResult()));errors.add(x);}return new Map<String,Object>{'success'=>r.isSuccess(),'errors'=>errors};
 }
