   } else if(key=='ST02') {Account a=account('Orchard Studio');insert a;out.put('exact',found(new List<SObject>{account('Orchard Studio')}));out.put('nameOnly',found(new List<SObject>{new Account(Name='Orchard Studio')}));out.put('miss',found(new List<SObject>{new Account(Name='Unrelated Planet')}));out.put('byIds',byIds(new List<Id>{a.Id}));}
